const sumNetOfChargeCodeOnFolio = `-- name: SumNetOfChargeCodeOnFolio :one
SELECT COALESCE(sum(net_amount), 0)::numeric AS net, count(*)::int AS items
FROM folio_items
WHERE property_id = $1 AND folio_id = $2 AND charge_code_id = $3
  AND transaction_type IN ('CHARGE', 'ADJUSTMENT', 'REVERSAL')
`

type SumNetOfChargeCodeOnFolioParams struct {
	PropertyID   int64
	FolioID      int64
	ChargeCodeID *int64
}

type SumNetOfChargeCodeOnFolioRow struct {
	Net   decimal.Decimal
	Items int32
}

// What a charge code has posted on a folio: the net of its charges, adjustments and reversals (a reversed charge nets out).
// An adjustment corrects this, so it needs it to be above zero and, for a credit, to stay within it.
func (q *Queries) SumNetOfChargeCodeOnFolio(ctx context.Context, arg SumNetOfChargeCodeOnFolioParams) (SumNetOfChargeCodeOnFolioRow, error) {
	row := q.db.QueryRow(ctx, sumNetOfChargeCodeOnFolio, arg.PropertyID, arg.FolioID, arg.ChargeCodeID)
	var i SumNetOfChargeCodeOnFolioRow
	err := row.Scan(&i.Net, &i.Items)
	return i, err
}

const sumRefundsOf = `-- name: SumRefundsOf :one
SELECT COALESCE(sum(amount), 0)::numeric AS refunded, count(*)::int AS refund_count
FROM payments WHERE property_id = $1 AND refund_of_payment_id = $2 AND status = 'POSTED'
`

type SumRefundsOfParams struct {
	PropertyID int64
	PaymentID  *int64
}

type SumRefundsOfRow struct {
	Refunded    decimal.Decimal
	RefundCount int32
}

// Refunds of a payment that were not voided (REFUND payments cannot be voided, so all of them count).
func (q *Queries) SumRefundsOf(ctx context.Context, arg SumRefundsOfParams) (SumRefundsOfRow, error) {
	row := q.db.QueryRow(ctx, sumRefundsOf, arg.PropertyID, arg.PaymentID)
	var i SumRefundsOfRow
	err := row.Scan(&i.Refunded, &i.RefundCount)
	return i, err
}

const unlinkFolioFromStay = `-- name: UnlinkFolioFromStay :one
UPDATE folios SET stay_id = NULL, version = version + 1, updated_by = $1
WHERE tenant_id = $2 AND property_id = $3 AND id = $4
RETURNING id, tenant_id, property_id, folio_number, reservation_id, stay_id, folio_type, status, opened_at, closed_at, closed_by, version, created_at, created_by, updated_at, updated_by, closed_on, bill_to_company_id
`

type UnlinkFolioFromStayParams struct {
	ActorID    *int64
	TenantID   int64
	PropertyID int64
	ID         int64
}

func (q *Queries) UnlinkFolioFromStay(ctx context.Context, arg UnlinkFolioFromStayParams) (Folio, error) {
	row := q.db.QueryRow(ctx, unlinkFolioFromStay,
		arg.ActorID,
		arg.TenantID,
		arg.PropertyID,
		arg.ID,
	)
	var i Folio
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.PropertyID,
		&i.FolioNumber,
		&i.ReservationID,
		&i.StayID,
		&i.FolioType,
		&i.Status,
		&i.OpenedAt,
		&i.ClosedAt,
		&i.ClosedBy,
		&i.Version,
		&i.CreatedAt,
		&i.CreatedBy,
		&i.UpdatedAt,
		&i.UpdatedBy,
		&i.ClosedOn,
		&i.BillToCompanyID,
	)
	return i, err
}

const voidPayment = `-- name: VoidPayment :one
UPDATE payments SET status = 'VOIDED', voided_at = $1::timestamptz, voided_by = $2, void_reason = $3, approved_by = $4
WHERE tenant_id = $5 AND property_id = $6 AND id = $7
RETURNING id, tenant_id, property_id, payment_number, folio_id, payment_type, payment_method, amount, paid_at, business_date, reference_number, refund_of_payment_id, status, voided_at, voided_by, void_reason, idempotency_key, remarks, created_at, created_by, approved_by, company_id, shift_id, mdr_rate, mdr_fee, expected_settlement_date, mdr_vat_rate, mdr_vat
`

type VoidPaymentParams struct {
	Now        time.Time
	ActorID    *int64
	Reason     *string
	ApprovedBy *int64
	TenantID   int64
	PropertyID int64
	ID         int64
}

func (q *Queries) VoidPayment(ctx context.Context, arg VoidPaymentParams) (Payment, error) {
	row := q.db.QueryRow(ctx, voidPayment,
		arg.Now,
		arg.ActorID,
		arg.Reason,
		arg.ApprovedBy,
		arg.TenantID,
		arg.PropertyID,
		arg.ID,
	)
	var i Payment
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.PropertyID,
		&i.PaymentNumber,
		&i.FolioID,
		&i.PaymentType,
		&i.PaymentMethod,
		&i.Amount,
		&i.PaidAt,
		&i.BusinessDate,
		&i.ReferenceNumber,
		&i.RefundOfPaymentID,
		&i.Status,
		&i.VoidedAt,
		&i.VoidedBy,
		&i.VoidReason,
		&i.IdempotencyKey,
		&i.Remarks,
		&i.CreatedAt,
		&i.CreatedBy,
		&i.ApprovedBy,
		&i.CompanyID,
		&i.ShiftID,
		&i.MdrRate,
		&i.MdrFee,
		&i.ExpectedSettlementDate,
		&i.MdrVatRate,
		&i.MdrVat,
	)
	return i, err
}
